import pinecone
from pinecone import Pinecone

pc = Pinecone(api_key="your-api-key")
index = pc.Index("enterprise-rag")

# Hybrid search with metadata filtering
results = index.query(
    namespace="risk-management",
    vector=dense_embedding,  # from embedding model
    sparse_vector={
        "indices": [42, 156, 889],
        "values": [0.8, 0.6, 0.4]
    },
    top_k=10,
    filter={
        "department": {"$eq": "compliance"},
        "clearance_level": {"$in": ["internal", "confidential"]}
    },
    include_metadata=True
)

// Entity resolution with fuzzy matching for customer MDM
MATCH (c1:Customer), (c2:Customer)
WHERE id(c1) < id(c2) 
  AND apoc.text.jaroWinklerDistance(c1.name, c2.name) > 0.9
  AND c1.domain = c2.domain
MERGE (c1)-[s:SIMILAR_TO]->(c2)
SET s.confidence = apoc.text.jaroWinklerDistance(c1.name, c2.name),
    s.detectedDate = date();

// Create golden record after manual review
MATCH (c:Customer)-[:SIMILAR_TO]->(duplicate:Customer)
WHERE c.reviewStatus = 'approved'
CALL apoc.refactor.mergeNodes([c, duplicate], {
  properties: 'combine',
  mergeRels: true
}) YIELD node
RETURN node
